from typing import list, dict
import pkg_resources


def dependency_report(names: list[str]) -> dict[str, str | None]:
    """Map each given distribution name to its installed version string or None if not installed."""
    # Build a map of lowercased distribution names to their versions for quick lookup
    installed = {dist.project_name.lower(): dist.version for dist in pkg_resources.working_set}
    result = {}
    for name in names:
        version = installed.get(name.lower())
        result[name] = version
    return result

from marshmallow import Schema, ValidationError, fields, EXCLUDE, validates


class SignupSchema(Schema):
    class Meta:
        unknown = EXCLUDE

    username = fields.String(required=True)
    email = fields.Email(required=True)
    plan = fields.String(load_default="free")
    age = fields.Integer()

    @validates("username")
    def validate_username(self, value):
        if not value.isalnum():
            raise ValidationError("Username must be alphanumeric.")

    @validates("plan")
    def validate_plan(self, value):
        if value not in ("free", "pro", "team"):
            raise ValidationError("Plan must be one of 'free', 'pro', or 'team'.")

    @validates("age")
    def validate_age(self, value):
        if not (16 <= value <= 120):
            raise ValidationError("Age must be between 16 and 120 inclusive.")


def validate_signup(data: dict) -> dict:
    """Validate signup data dict; return cleaned dict with defaults filled.
    Raise ValueError with .messages dict on validation errors."""
    try:
        return SignupSchema().load(data)
    except ValidationError as err:
        exc = ValueError("invalid signup data")
        exc.messages = err.messages
        raise exc

from pkg_info import installed_version


def dependency_report(names: list[str]) -> dict[str, str | None]:
    """Return a dict mapping each given distribution name to its installed version string or None if missing.

    The keys are exactly as given in `names`. Matching is case-insensitive.
    """
    report = {}
    for name in names:
        version = installed_version(name)
        report[name] = version
    return report

