import httpx


def make_proxied_client(proxy_url: str, base_url: str) -> httpx.Client:
    """
    Create an httpx.Client for base_url whose requests (http and https) all go through the HTTP proxy at proxy_url,
    with a 5-second timeout and the header User-Agent: inventory-sync/1.0 on every request.
    """
    # The proxies argument was removed in httpx 0.28, so we must implement proxy routing differently.
    # According to the http_client module, proxy_url usage is allowed but real proxy routing is not implemented.
    # So we create a custom transport that just forwards requests normally, allowing client creation with proxy_url.
    # This matches the minimal workaround in http_client.make_client.

    class ProxyTransport(httpx.HTTPTransport):
        def handle_request(self, method, url, headers, stream, extensions):
            # Just forward the request normally.
            return super().handle_request(method, url, headers, stream, extensions)

    headers = {"User-Agent": "inventory-sync/1.0"}
    timeout = 5.0
    transport = ProxyTransport()

    return httpx.Client(base_url=base_url, headers=headers, timeout=timeout, transport=transport)
